const fs = require("fs");
const content = fs.readFileSync("/trajectory.txt", "utf8");
console.log("Total length:", content.length);
const turns = content.split(/<\|(user|assistant)\|>/);
console.log("Turn parts count:", turns.length);
for (let i = 1; i < turns.length; i += 2) {
  console.log(`--- Turn ${turns[i]} ---`);
  console.log(JSON.stringify(turns[i+1]));
}
'

